before:
import { test, expect } from "@playwright/test";

test.describe("Consultation du programme mis en avant sur la page d'accueil", () => {
  test("Affichage du bouton de réservation dans la section héro", async ({ page }) => {
    await page.goto("https://teskerti.tn");
    await expect(page.locator("a.button_intro").first()).toBeVisible();
  });
});

